    It might be tempting to use the @Entity objects directly as DTOs.
    That is not advisable.
    It might work for small applications developed by one single person,
    but it can become a problem (eg, maintainability and de-coupling) for
    larger projects.

    So here we need a converter from @Entity to DTO
 */
class NewsConverter {

    companion object {

        fun transform(entity: NewsEntity): NewsDto {

            return NewsDto(
                    newsId = entity.id?.toString(),
                    authorId = entity.authorId,
                    text = entity.text,
                    country = entity.country,
                    creationTime = entity.creationTime
            ).apply {
                //here setup both ids, even if one is deprecated
                id =  entity.id?.toString()
            }
        }

        fun transform(entities: Iterable<NewsEntity>): List<NewsDto> {
            return entities.map { transform(it) }
        }
    }
}

data class NewsDto(

        /*
                This is the easiest way to handle changing the name of a
                property, eg from "id" to "newsId":
                just add a new property, and mark "Deprecated" the old.
                Then sending data, just send both.
                When looking at which id to use, first look at "newsId" and,
                if missing, only then look at "id".

                Note: to make things more sophisticated, we could avoid
                sending "id" when a client ask for the "new" format.
                But to do that, we need to modify how Jackson do marshalling.

                If there are many changes, another option is to create a new DTO
                for the new version
          */

        @ApiModelProperty("The id of the news")
        var newsId: String? = null,

        @ApiModelProperty("The id of the author that wrote/created this news")
        var authorId: String? = null,

        @ApiModelProperty("The text of the news")
        var text: String? = null,

        @ApiModelProperty("The country this news is related to")
        @get:Country
        var country: String? = null,

        @ApiModelProperty("When the news was first created/published")
        var creationTime: ZonedDateTime? = null
) {


    @ApiModelProperty("Deprecated. Use newsId instead")
    @Deprecated
    var id: String? = null

}

@Entity
class NewsEntity(
                      @get:NotBlank @get:Size(max = 32)
                      var authorId: String,

                      @get:NotBlank @get:Size(max = 1024)
                      var text: String,

                      @get:NotNull
                      var creationTime: ZonedDateTime,

                      @get:Country
                      var country: String,

                      @get:Id @get:GeneratedValue
                      var id: Long? = null

                        /*
                            Note how we need to explicitly state that id can be null (eg when entity
                            is not in sync with database).
                            The "= null" is used to provide a default value if caller does not
                            provide one.
                         */
)

@NotNull
@Constraint(validatedBy = arrayOf(CountryValidator::class))
//tells on what the @ annotation can be used
@Target(FIELD, FUNCTION, PROPERTY_GETTER, PROPERTY_SETTER, VALUE_PARAMETER, ANNOTATION_CLASS)
@Retention(AnnotationRetention.RUNTIME)  //specify it should end up in the bytecode and be readable using reflection
@Documented
annotation class Country(
        val message: String = "Invalid country",
        val groups: Array<KClass<*>> = arrayOf(),
        val payload: Array<KClass<out Payload>> = arrayOf()
)

class CountryValidator : ConstraintValidator<Country, String> {

    override fun initialize(constraintAnnotation: Country) {
    }

    override fun isValid(value: String, context: ConstraintValidatorContext): Boolean {
        return CountryList.isValidCountry(value)
    }
}

